class Solution {
public:
    long long maximumCoins(vector<vector<int>>& coins, int k) {
        sort(coins.begin(), coins.end(), [](const auto& a, const auto& b) {
            return a[0] < b[0];
        });

        auto solve = [](const vector<vector<int>>& arr, int length) -> long long {
            int n = arr.size();
            long long maxC = 0, currC = 0;
            int j = 0;
            for (int i = 0; i < n; ++i) {
                long long start = arr[i][0];
                long long end = start + length - 1;
                while (j < n && arr[j][0] <= end) {
                    long long ol = max(start, (long long)arr[j][0]);
                    long long orr = min(end, (long long)arr[j][1]);
                    if (ol <= orr) {
                        currC += (orr - ol + 1) * (long long)arr[j][2];
                    }
                    j++;
                }
                maxC = max(maxC, currC);
                long long ol = max(start, (long long)arr[i][0]);
                long long orr = min(end, (long long)arr[i][1]);
                if (ol <= orr) {
                    currC -= (orr - ol + 1) * (long long)arr[i][2];
                }
            }
            return maxC;
        };

        long long ans = solve(coins, k);
        vector<vector<int>> revCoins;
        for (int i = (int)coins.size() - 1; i >= 0; --i) {
            revCoins.push_back({-coins[i][1], -coins[i][0], coins[i][2]});
        }
        ans = max(ans, solve(revCoins, k));
        return ans;
    }
};

class Solution {
    public long maximumCoins(int[][] coins, int k) {
        Arrays.sort(coins, (a, b) -> Integer.compare(a[0], b[0]));

        long ans = solve(coins, k);
        int n = coins.length;
        int[][] revCoins = new int[n][3];
        for (int i = 0; i < n; ++i) {
            revCoins[i][0] = -coins[n - 1 - i][1];
            revCoins[i][1] = -coins[n - 1 - i][0];
            revCoins[i][2] = coins[n - 1 - i][2];
        }
        ans = Math.max(ans, solve(revCoins, k));
        return ans;
    }

    private long solve(int[][] arr, int length) {
        int n = arr.length;
        long maxC = 0, currC = 0;
        int j = 0;
        for (int i = 0; i < n; ++i) {
            long start = arr[i][0];
            long end = start + length - 1;
            while (j < n && arr[j][0] <= end) {
                long ol = Math.max(start, arr[j][0]);
                long orr = Math.min(end, arr[j][1]);
                if (ol <= orr) {
                    currC += (orr - ol + 1) * (long)arr[j][2];
                }
                j++;
            }
            maxC = Math.max(maxC, currC);
            long ol = Math.max(start, arr[i][0]);
            long orr = Math.min(end, arr[i][1]);
            if (ol <= orr) {
                currC -= (orr - ol + 1) * (long)arr[i][2];
            }
        }
        return maxC;
    }
}

var maximumCoins = function(coins, k) {
    coins.sort((a, b) => a[0] - b[0]);

    const solve = (arr, length) => {
        const n = arr.length;
        let maxC = 0n, currC = 0n;
        let j = 0;
        const lenBig = BigInt(length);
        for (let i = 0; i < n; ++i) {
            const start = BigInt(arr[i][0]);
            const end = start + lenBig - 1n;
            while (j < n && BigInt(arr[j][0]) <= end) {
                const j0 = BigInt(arr[j][0]), j1 = BigInt(arr[j][1]), j2 = BigInt(arr[j][2]);
                const ol = start > j0 ? start : j0;
                const orr = end < j1 ? end : j1;
                if (ol <= orr) {
                    currC += (orr - ol + 1n) * j2;
                }
                j++;
            }
            if (currC > maxC) maxC = currC;
            const i0 = BigInt(arr[i][0]), i1 = BigInt(arr[i][1]), i2 = BigInt(arr[i][2]);
            const ol = start > i0 ? start : i0;
            const orr = end < i1 ? end : i1;
            if (ol <= orr) {
                currC -= (orr - ol + 1n) * i2;
            }
        }
        return maxC;
    };

    let ans = solve(coins, k);
    const revCoins = coins.slice().reverse().map(([l, r, c]) => [-r, -l, c]);
    const revAns = solve(revCoins, k);
    return Number(ans > revAns ? ans : revAns);
};
